function wsUrl(){return `${location.protocol==='https:'?'wss':'ws'}://${location.host}/api/ws?token=${encodeURIComponent(authToken)}`;}
function getLiveSocket(){return new Promise((resolve,reject)=>{const socket=new WebSocket(wsUrl());liveSocket=socket;socket.onopen=()=>resolve(socket);socket.onerror=()=>reject(new Error('Could not connect to the live room. Check Wi-Fi and HTTPS.'));socket.onmessage=event=>handleLiveEvent(JSON.parse(event.data));socket.onclose=()=>{liveSocket=null;};});}
function signal(payload){if(liveSocket?.readyState===WebSocket.OPEN)liveSocket.send(JSON.stringify(payload));}
function participantVideo(stream){const video=$('#participant-video');if(!video)return;const media=stream||participantMedia;if(!media)return;if(video.srcObject!==media)video.srcObject=media;video.onplaying=()=>{const status=$('#live-connection-status');if(status)status.textContent='Live video is playing';};video.onloadedmetadata=()=>video.play().catch(()=>{const status=$('#live-connection-status');if(status)status.textContent='Live video connected. Tap play to start playback.';});if(video.readyState>=HTMLMediaElement.HAVE_METADATA)video.play().catch(()=>{const status=$('#live-connection-status');if(status)status.textContent='Live video connected. Tap play to start playback.';});}
function attachParticipantLiveVideo(){participantVideo(participantMedia);const status=$('#live-connection-status');if(status&&participantMedia&&!participantMedia.getVideoTracks().some(track=>track.readyState==='live'))status.textContent='Waiting for the organiser’s video…';}
function makePeer(peerId){if(peerConnections.has(peerId))return peerConnections.get(peerId);const pc=new RTCPeerConnection({iceServers:liveIceServers});if(liveStream)liveStream.getTracks().forEach(track=>pc.addTrack(track,liveStream));pc.onicecandidate=event=>{if(event.candidate)signal({type:'ice',to:peerId,candidate:event.candidate});};pc.ontrack=event=>{const incoming=event.streams?.[0];if(incoming)participantMedia=incoming;else{participantMedia=participantMedia||new MediaStream();if(!participantMedia.getTracks().some(track=>track.id===event.track.id))participantMedia.addTrack(event.track);}participantVideo(participantMedia);};pc.onconnectionstatechange=()=>{const status=$('#live-connection-status');if(status)status.textContent=pc.connectionState==='connected'?'Video connected to the live class':pc.connectionState==='failed'?'Video connection failed. Ask the administrator to configure STUN/TURN for this network.':pc.connectionState;};peerConnections.set(peerId,pc);return pc;}
async function offerPeer(peerId){const pc=makePeer(peerId);const offer=await pc.createOffer();await pc.setLocalDescription(offer);signal({type:'offer',to:peerId,description:pc.localDescription});}
async function handleLiveEvent(message){
  if(message.type==='error'){toast(message.message);return;}
  if(message.type==='joined'){
    message.peers.forEach(id=>makePeer(id));
    const status=$('#live-connection-status');if(status)status.textContent='Connected to the live room';
  }else if(message.type==='peer_joined'){
    if(role!=='participant')await offerPeer(message.peer);
  }else if(message.type==='offer'){
    const pc=makePeer(message.peer);await pc.setRemoteDescription(message.description);for(const candidate of pendingIceCandidates.get(message.peer)||[])await pc.addIceCandidate(candidate);pendingIceCandidates.delete(message.peer);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);signal({type:'answer',to:message.peer,description:pc.localDescription});
  }else if(message.type==='answer'){
    const pc=peerConnections.get(message.peer);if(pc){await pc.setRemoteDescription(message.description);for(const candidate of pendingIceCandidates.get(message.peer)||[])await pc.addIceCandidate(candidate);pendingIceCandidates.delete(message.peer);}
  }else if(message.type==='ice'){
    const pc=makePeer(message.peer);if(message.candidate){if(pc.remoteDescription)await pc.addIceCandidate(message.candidate);else pendingIceCandidates.set(message.peer,[...(pendingIceCandidates.get(message.peer)||[]),message.candidate]);}
  }else if(message.type==='peer_left'){
    peerConnections.get(message.peer)?.close();peerConnections.delete(message.peer);participantMedia=null;
  }else if(message.type==='caption'){
    const caption=$('#live-caption-text');if(caption)caption.textContent=message.caption||'';
    const panel=$('#live-caption-panel');if(panel)panel.hidden=!message.caption;
  }else if(message.type==='live_chat'){
    const chatMessage=message.message;
    if(chatMessage&&!liveChatMessages.some(item=>item.id===chatMessage.id)){liveChatMessages.push(chatMessage);renderLiveChatMessages();}
  }else if(message.type==='message'||message.type==='followup'){
    await hydrate();if(page==='Messages')render();toast('You have a new Voxera message.');
  }
}
function joinRoom(id){return getLiveSocket().then(socket=>{socket.send(JSON.stringify({type:'join_live',session_id:id}));return socket;});}
function renderLiveChatMessages(){
  const list=$('#live-chat-messages');if(!list)return;
  list.innerHTML=liveChatMessagesMarkup();
  list.scrollTop=list.scrollHeight;
}
function liveChatMessagesMarkup(){return liveChatMessages.map(message=>`<div class="live-chat-message"><b>${esc(message.user_name||'Participant')}</b><p>${esc(message.body)}</p><time>${esc(new Date(message.created_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}))}</time></div>`).join('')||'<div class="empty">Say hello to everyone in the class.</div>';}
function liveChatPanel(){
  return `<section class="live-chat-widget"><button class="live-chat-toggle" type="button" onclick="toggleLiveChat()" aria-expanded="${liveChatExpanded}" aria-controls="live-chat-panel"><span aria-hidden="true">▤</span><b>Live chat</b><span class="live-chat-chevron">${liveChatExpanded?'⌄':'⌃'}</span></button><div id="live-chat-panel" class="live-chat-panel" ${liveChatExpanded?'':'hidden'}><div class="live-chat-heading"><div><b>Live chat</b><small>Messages are visible to everyone in this session.</small></div><button type="button" class="text-link" onclick="toggleLiveChat()">Hide</button></div><div id="live-chat-messages" class="live-chat-messages">${liveChatMessagesMarkup()}</div><form class="live-chat-compose" onsubmit="sendLiveChat(event)"><input id="live-chat-input" maxlength="1000" placeholder="Send a message…" autocomplete="off" aria-label="Live chat message"><button class="btn btn-primary btn-small" type="submit">Send</button></form></div></section>`;
}
async function toggleLiveChat(){
  liveChatExpanded=!liveChatExpanded;
  const panel=$('#live-chat-panel');const button=$('.live-chat-toggle');
  if(panel)panel.hidden=!liveChatExpanded;if(button){button.setAttribute('aria-expanded',String(liveChatExpanded));const chevron=button.querySelector('.live-chat-chevron');if(chevron)chevron.textContent=liveChatExpanded?'⌄':'⌃';}
  if(liveChatExpanded&&liveChatSessionId){try{liveChatMessages=await api(`/api/sessions/${liveChatSessionId}/live-chat`);renderLiveChatMessages();}catch(error){toast(error.message);}}
}
function sendLiveChat(event){
  event.preventDefault();const input=$('#live-chat-input');const body=input?.value.trim();
  if(!body)return;if(!liveSocket||liveSocket.readyState!==WebSocket.OPEN)return toast('Live chat is disconnected. Rejoin the session and try again.');
  liveSocket.send(JSON.stringify({type:'live_chat',body}));input.value='';
}
function videoCommentsMarkup(){
  return `<section class="video-comments"><div class="video-comments-heading"><div><b>Comments</b><small>Discuss this class with enrolled participants and the programme team.</small></div></div><div id="video-comment-list">${videoComments.map(comment=>`<article class="video-comment"><b>${esc(comment.user_name||'Former participant')}</b><time>${esc(new Date(comment.created_at).toLocaleString())}</time><p>${esc(comment.body)}</p></article>`).join('')||'<div class="empty">No comments yet. Start the conversation.</div>'}</div><form class="video-comment-compose" onsubmit="submitVideoComment(event)"><textarea id="video-comment-input" maxlength="1000" rows="2" placeholder="Add a comment…" aria-label="Add a comment"></textarea><button class="btn btn-primary btn-small" type="submit">Comment</button></form></section>`;
}
async function loadVideoComments(sessionId){
  videoCommentSessionId=Number(sessionId);videoComments=await api(`/api/sessions/${videoCommentSessionId}/comments`);
  const panel=$('#video-comment-list');if(panel)panel.innerHTML=videoCommentsMarkup().match(/<div id="video-comment-list">([\s\S]*)<\/div><form/)[1];
}
async function submitVideoComment(event){
  event.preventDefault();const input=$('#video-comment-input'),body=input?.value.trim();
  if(!body)return toast('Write a comment before posting.');
  try{const result=await api(`/api/sessions/${videoCommentSessionId}/comments`,{method:'POST',body:JSON.stringify({body})});videoComments.push(result);input.value='';const list=$('#video-comment-list');if(list)list.innerHTML=videoComments.map(comment=>`<article class="video-comment"><b>${esc(comment.user_name||'Former participant')}</b><time>${esc(new Date(comment.created_at).toLocaleString())}</time><p>${esc(comment.body)}</p></article>`).join('');}catch(error){toast(error.message);}
}
function vttTime(seconds){const value=Math.max(0,Math.round(seconds*1000));const hours=Math.floor(value/3600000);const minutes=Math.floor(value%3600000/60000);const secs=Math.floor(value%60000/1000);const millis=value%1000;return `${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(secs).padStart(2,'0')}.${String(millis).padStart(3,'0')}`;}
function startLiveCaptions(){
  const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!Recognition){toast('Automatic captions are not supported by this browser. The live class will continue without captions.');liveCaptionsEnabled=false;return;}
  liveCaptionRecognition=new Recognition();liveCaptionRecognition.lang='en';liveCaptionRecognition.continuous=true;liveCaptionRecognition.interimResults=true;
  liveCaptionRecognition.onresult=event=>{
    let interim='';
    for(let index=event.resultIndex;index<event.results.length;index++){
      const result=event.results[index];const text=result[0]?.transcript?.trim();if(!text)continue;
      if(result.isFinal){
        const end=(Date.now()-liveStartedAt)/1000;const duration=Math.min(6,Math.max(2,text.split(/\s+/).length/2.5));const start=Math.max(liveCaptionEntries.length?liveCaptionEntries[liveCaptionEntries.length-1].end:0,end-duration);
        const cue={start,end:Math.max(start+0.5,end),text};liveCaptionEntries.push(cue);signal({type:'caption',caption:text});
      }else interim+=text;
    }
    const caption=$('#live-caption-text');if(caption)caption.textContent=interim||liveCaptionEntries[liveCaptionEntries.length-1]?.text||'';
    const panel=$('#live-caption-panel');if(panel)panel.hidden=false;
  };
  liveCaptionRecognition.onerror=event=>{if(event.error!=='no-speech'&&event.error!=='aborted')toast(`Automatic captions stopped: ${event.error}.`);};
  liveCaptionRecognition.onend=()=>{if(liveCaptionsEnabled&&state.live)try{liveCaptionRecognition.start();}catch{}};
  try{liveCaptionRecognition.start();}catch(error){liveCaptionsEnabled=false;liveCaptionRecognition=null;toast(`Could not start automatic captions: ${error.message}`);}
}
async function stopLiveCaptions(){
  const recognition=liveCaptionRecognition;liveCaptionsEnabled=false;liveCaptionRecognition=null;
  if(recognition){await new Promise(resolve=>{const timer=setTimeout(resolve,800);recognition.onend=()=>{clearTimeout(timer);resolve();};try{recognition.stop();}catch{clearTimeout(timer);resolve();}});}
}
function liveCaptionsVtt(){return liveCaptionEntries.length?`WEBVTT\n\n${liveCaptionEntries.map(cue=>`${vttTime(cue.start)} --> ${vttTime(cue.end)}\n${cue.text}`).join('\n\n')}\n`:'';}
async function startLive(recordRecording,enableCaptions,keepAvailable){
  const sessionId=Number(selectedSessionId);
  if(!sessionId){toast('Choose a real session before starting live class.');return;}
  let serverStarted=false;
  try{
    if(!navigator.mediaDevices?.getUserMedia){throw new Error('Live video requires a supported browser and a secure connection (HTTPS, or localhost).');}
    if(recordRecording&&!window.MediaRecorder)throw new Error('This browser cannot record the live session. Uncheck “Save this live recording” and try again.');
    liveStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});
    const preview=$('#organiser-video');if(preview){preview.srcObject=liveStream;preview.muted=true;preview.play().catch(()=>{});}
    const result=await api(`/api/sessions/${sessionId}/live`,{method:'POST',body:JSON.stringify({active:true})});serverStarted=true;liveIceServers=result.ice_servers||[];
    await joinRoom(sessionId);
    liveChatSessionId=sessionId;liveChatMessages=await api(`/api/sessions/${sessionId}/live-chat`);
    saveLiveRecording=recordRecording;liveKeepAvailable=keepAvailable;liveCaptionsEnabled=enableCaptions;liveCaptionEntries=[];liveStartedAt=Date.now();
    if(saveLiveRecording){liveChunks=[];const mime=MediaRecorder.isTypeSupported?.('video/webm;codecs=vp8,opus')?'video/webm;codecs=vp8,opus':MediaRecorder.isTypeSupported?.('video/webm')?'video/webm':'';liveRecorder=mime?new MediaRecorder(liveStream,{mimeType:mime}):new MediaRecorder(liveStream);liveRecorder.ondataavailable=e=>{if(e.data.size)liveChunks.push(e.data);};liveRecorder.onerror=event=>toast(`Live recording failed: ${event.error?.message||'browser recorder error'}`);liveRecorder.start(1000);}
    state.live=true;if(liveCaptionsEnabled)startLiveCaptions();render();const livePreview=$('#organiser-video');if(livePreview){livePreview.srcObject=liveStream;livePreview.muted=true;livePreview.play().catch(()=>{});}toast(`Live session started${saveLiveRecording?' · recording will be saved':' · recording will not be saved'}${liveCaptionsEnabled?' · captions on':''}. Participants can join now.`);
    liveRefreshTimer=setInterval(refreshLivePresence,5000);
  }catch(error){if(serverStarted)try{await api(`/api/sessions/${sessionId}/live`,{method:'POST',body:JSON.stringify({active:false})});}catch(stopError){toast(`Could not reset the live session: ${stopError.message}`);}liveSocket?.close();liveSocket=null;liveStream?.getTracks().forEach(track=>track.stop());liveStream=null;if(liveRecorder?.state==='recording')liveRecorder.stop();liveRecorder=null;liveIceServers=[];state.live=false;toast(error.message||'Camera or microphone could not start. Allow access and try again.');}
}
async function refreshLivePresence(){try{const sessionId=Number(selectedSessionId);if(!sessionId)return;const session=(state.sessionsByProgramme?.[selectedProgrammeId]||[]).find(s=>s.id===sessionId);const duration=session?Math.max(1,(new Date(session.scheduled_end)-new Date(session.scheduled_start))/1000):3600;const rows=await api(`/api/sessions/${sessionId}/presence`);const list=$('#live-participant-list');if(list)list.innerHTML=rows.length?rows.map(p=>`<div class="risk"><span class="mini-avatar">${esc(p.participant_name.split(' ').map(x=>x[0]).join('').slice(0,2))}</span><div class="risk-name">${esc(p.participant_name)}<div class="risk-meta">${p.visible?'Active in session':'Background or disconnected'}</div></div><div class="progress" style="width:100px"><i style="width:${Math.min(100,Math.round(p.seconds/duration*100))}%"></i></div><span class="badge">${Math.min(100,Math.round(p.seconds/duration*100))}%</span></div>`).join(''):'<div class="empty">No participants have joined yet.</div>';}catch{}}
async function stopLive(){
  if(!liveStream)return;
  const sessionId=Number(selectedSessionId);
  clearInterval(liveRefreshTimer);state.live=false;await stopLiveCaptions();signal({type:'leave_live'});liveSocket?.close();liveSocket=null;
  const recorder=liveRecorder;
  const blobPromise=recorder?.state==='recording'?new Promise(resolve=>{recorder.addEventListener('stop',()=>resolve(new Blob(liveChunks,{type:recorder.mimeType||'video/webm'})),{once:true});recorder.stop();}):Promise.resolve(null);
  try{const result=await api(`/api/sessions/${sessionId}/live`,{method:'POST',body:JSON.stringify({active:false})});toast(`Session ended · ${result.participants} participants connected.`);}catch(error){toast(`Session ended locally, but server attendance could not be finalized: ${error.message}`);}
  const blob=await blobPromise;
  if(saveLiveRecording){
    if(blob?.size){const form=new FormData();form.append('file',blob,`session-${sessionId}.webm`);form.append('keep_available',String(liveKeepAvailable));const vtt=liveCaptionEntries.length?liveCaptionsVtt():'';if(vtt)form.append('captions',new Blob([vtt],{type:'text/vtt'}),`session-${sessionId}.vtt`);try{const response=await fetch(`/api/sessions/${sessionId}/recording`,{method:'POST',headers:{Authorization:'Bearer '+authToken},body:form});const result=await response.json();if(!response.ok)throw new Error(result.detail||'Recording upload failed.');selectedSessionId=sessionId;page='Programme Classes';toast(result.keep_available?'Recording saved without an expiry date. Find it under Programmes → Classes.':result.captions_available?'Recording and captions saved. Find them under Programmes → Classes.':'Recording saved. Find it under Programmes → Classes.');}catch(error){toast(`Recording could not be saved: ${error.message}`);}}
    else toast('The live session ended, but the browser produced no recording data.');
  }else toast('Live session ended. No recording was saved.');
  selectedSessionId=sessionId;
  page='Programme Classes';
  liveStream.getTracks().forEach(track=>track.stop());liveStream=null;liveRecorder=null;peerConnections.forEach(pc=>pc.close());peerConnections.clear();saveLiveRecording=false;liveKeepAvailable=false;liveCaptionEntries=[];liveChatMessages=[];liveChatSessionId=null;liveChatExpanded=false;state.live=false;await hydrate();render();liveIceServers=[];
}
async function toggleLive(){if(state.live)await stopLive();else{const save=$('#save-live-recording')?.checked||false;const captions=$('#enable-live-captions')?.checked||false;const keepAvailable=$('#recording-keep-available')?.checked||false;await startLive(save,captions,keepAvailable);}}
async function joinLiveClass(id){const sessionId=Number(id||selectedSessionId);if(!sessionId){toast('Choose an upcoming session first.');return;}selectedSessionId=sessionId;participantMedia=null;peerConnections.forEach(pc=>pc.close());peerConnections.clear();pendingIceCandidates.clear();page='Live Class';render();try{const room=await api(`/api/sessions/${sessionId}/live`);if(room.state!=='live'){toast('The organiser has not started this session yet.');page='Programme Detail';render();return;}state.liveRoom=room;liveIceServers=room.ice_servers||[];liveChatSessionId=sessionId;liveChatMessages=[];await joinRoom(sessionId);liveChatMessages=await api(`/api/sessions/${sessionId}/live-chat`);render();attachParticipantLiveVideo();clearInterval(livePresenceTimer);if(liveVisibilityHandler)document.removeEventListener('visibilitychange',liveVisibilityHandler);const heartbeat=async()=>{if(page!=='Live Class')return;try{const result=await api(`/api/sessions/${sessionId}/heartbeat`,{method:'POST',body:JSON.stringify({visible:document.visibilityState==='visible'})});state.livePresence=result;}catch(error){clearInterval(livePresenceTimer);toast(error.message);}};liveVisibilityHandler=heartbeat;await heartbeat();livePresenceTimer=setInterval(heartbeat,10000);document.addEventListener('visibilitychange',liveVisibilityHandler);toast('You joined the live session. Stay on this screen for attendance.');}catch(error){toast(error.message);}}
function participantLive(){return `<div class="hello">LIVE PROGRAMME SESSION</div><h1 class="phone-title">${esc(state.liveRoom?.session_title||'Live session')}</h1><div class="phone-card"><div class="media-stage"><video id="participant-video" autoplay playsinline controls></video><div class="video-label">LIVE · ${esc(state.liveRoom?.programme_title||'')}</div></div><div class="profile-option"><span id="live-connection-status">Connecting to the organiser…</span><span class="badge">● Live</span></div><div class="notice">Your presence is counted while this screen is visible. Keep Voxera open; the video pauses when you leave.</div><div class="row-meta">Your current presence: ${percent((state.livePresence?.present_seconds||0)/Math.max(1,(new Date((state.liveRoom?.ended_at||state.liveRoom?.started_at||Date.now()))-new Date(state.liveRoom?.started_at||Date.now())))*100)}</div><button class="btn btn-outline" onclick="leaveLive()">Leave session</button></div>`;}
const participantLiveWithoutCaptions=participantLive;
participantLive=function(){return participantLiveWithoutCaptions().replace('</video><div class="video-label">LIVE ·','</video><div id="live-caption-panel" class="live-caption-panel participant-live-caption" hidden><span class="eyebrow">LIVE CAPTION</span><div id="live-caption-text"></div></div><div class="video-label">LIVE ·').replace('</div><div class="notice">Your presence is counted',`</div>${liveChatPanel()}<div class="notice">Your presence is counted`);};
function leaveLive(){signal({type:'leave_live'});liveSocket?.close();liveSocket=null;clearInterval(livePresenceTimer);if(liveVisibilityHandler)document.removeEventListener('visibilitychange',liveVisibilityHandler);liveVisibilityHandler=null;peerConnections.forEach(pc=>pc.close());peerConnections.clear();pendingIceCandidates.clear();participantMedia=null;liveIceServers=[];liveChatMessages=[];liveChatSessionId=null;liveChatExpanded=false;page='Programme Detail';render();}
function liveClass(){const programmes=state.programmes||[];const programme=programmes.find(p=>p.id===selectedProgrammeId)||programmes[0];if(programme)selectedProgrammeId=programme.id;const sessions=programme?state.sessionsByProgramme?.[programme.id]||[]:[];if(!sessions.some(s=>s.id===selectedSessionId))selectedSessionId=sessions[0]?.id||null;return `${head('TOGETHER, IN REAL TIME','Live class','Start a scheduled session. Participants who are enrolled can join from their phones.')}<section class="grid split"><div class="card"><div class="field"><label>Programme</label><select class="select" onchange="selectLiveProgramme(this.value)">${programmes.map(p=>`<option value="${p.id}" ${p.id===programme?.id?'selected':''}>${esc(p.title)}</option>`).join('')||'<option value="">No programmes yet</option>'}</select></div><div class="field"><label>Session</label><select class="select" onchange="selectLiveSession(this.value)">${sessions.map(s=>`<option value="${s.id}" ${s.id===selectedSessionId?'selected':''}>${esc(s.title)} · ${dateLabel(s.scheduled_start)}</option>`).join('')||'<option value="">No sessions scheduled</option>'}</select></div><div class="notice">Your browser will request webcam and microphone access. Recording is uploaded to this local server when the session ends.</div><button class="btn ${state.live?'btn-soft':'btn-primary'}" onclick="toggleLive()" ${!selectedSessionId?'disabled':''}>${state.live?'End session and save recording':'Start live session'}</button></div><div class="card"><div class="media-stage"><video id="organiser-video" autoplay muted playsinline></video><div class="video-label">${state.live?'● LIVE':'Camera preview appears here'}</div></div></div></section><article class="card" style="margin-top:16px"><div class="card-head"><div class="card-title">Participant presence</div><span class="row-meta">Attendance requires at least 70% of session duration</span></div><div id="live-participant-list" class="programme-list"><div class="empty">Presence updates when enrolled participants join.</div></div></article>`;}
