  input.disabled=true;
  try{const result=await api(`/api/sessions/${selectedSessionId}/recording-availability`,{method:'PATCH',body:JSON.stringify({keep_available:input.checked})});session.recording_no_expiry=Number(result.keep_available);toast(result.keep_available?'Video will stay available without an expiry date.':'Video availability will end after the session deadline.');}
  catch(error){input.checked=!input.checked;toast(error.message);}
