async function approveEnrollment(id,status){try{await api(`/api/enrolments/${id}`,{method:'PATCH',body:JSON.stringify({status})});await hydrate();render();toast(`Application ${status==='enrolled'?'approved':status}.`);}catch(error){toast(error.message);}}

function watchRecording(sessionId){selectedSessionId=Number(sessionId||selectedSessionId);if(!selectedSessionId)return toast('Recording session not found.');const id=selectedSessionId;const overlay=document.createElement('div');overlay.className='modal-back';overlay.innerHTML=`<div class="modal" style="width:min(760px,100%)"><div class="modal-top"><div><h2>Session recording</h2><p>Only time watched at a normal pace is counted. Skipping ahead does not count.</p></div><button class="close" onclick="closeWatch()">×</button></div><div class="media-stage"><video id="watch-video" controls playsinline preload="metadata"></video></div><div class="progress-row"><span id="watch-percent">Watched 0%</span><b id="watch-needed">70% needed</b></div><div class="progress lime"><i id="watch-progress-bar" style="width:0%"></i></div><div id="checkin-overlay" class="notice" style="display:none;margin-top:12px"><b>Quick check-in</b><br>Tap below to keep watching.</div><button id="checkin-continue" class="btn btn-primary btn-small" style="display:none" onclick="continueWatch()">Tap to continue</button><div id="quiz-wrap" style="margin-top:12px"></div><label class="profile-option"><span>Low-data playback</span><input id="low-data-toggle" type="checkbox" onchange="setLowData()"></label></div>`;document.body.append(overlay);watchSegments=[];watchCheckpoints=[];watchCheckpointIndex=0;watchComplete=false;quizLoaded=false;watchVideo=$('#watch-video');watchVideo.src=`/api/sessions/${id}/recording?token=${encodeURIComponent(authToken)}`;watchVideo.onloadedmetadata=()=>{const duration=watchVideo.duration;watchCheckpoints=[duration*(0.27+Math.random()*.14),duration*(0.58+Math.random()*.12)];};watchVideo.addEventListener('seeking',()=>{watchSeeking=true;});watchVideo.addEventListener('seeked',()=>{watchLastTime=watchVideo.currentTime;watchLastWall=Date.now();setTimeout(()=>watchSeeking=false,100);});watchVideo.addEventListener('ratechange',()=>{if(watchVideo.playbackRate>1.5)watchVideo.playbackRate=1.5;});watchVideo.addEventListener('play',()=>{watchLastTime=watchVideo.currentTime;watchLastWall=Date.now();});watchVideo.addEventListener('timeupdate',watchTick);watchProgressTimer=setInterval(pushWatchProgress,5000);document.addEventListener('visibilitychange',pauseBackground);watchVideo.onerror=()=>toast('Recording unavailable or the recording deadline has passed.');}
function updateWatchProgressUI(){if(!watchVideo?.duration)return;const sorted=watchSegments.map(segment=>[Math.max(0,Number(segment[0])||0),Math.min(watchVideo.duration,Number(segment[1])||0)]).filter(segment=>segment[1]>segment[0]).sort((a,b)=>a[0]-b[0]);const merged=[];for(const segment of sorted){if(merged.length&&segment[0]<=merged[merged.length-1][1]+0.5)merged[merged.length-1][1]=Math.max(merged[merged.length-1][1],segment[1]);else merged.push(segment);}const seconds=merged.reduce((total,segment)=>total+segment[1]-segment[0],0);const pct=Math.min(100,seconds/watchVideo.duration*100);$('#watch-percent').textContent=`Watched ${pct.toFixed(1)}%`;$('#watch-needed').textContent=pct>=70?'Quiz unlocked':`${Math.max(0,70-pct).toFixed(0)}% more needed`;$(`#watch-progress-bar`)?.style.setProperty('width',`${pct}%`);$('#watch-progress-bar')?.setAttribute('aria-valuenow',String(Math.round(pct)));}
function watchTick(){if(!watchVideo||watchVideo.paused)return;const current=watchVideo.currentTime;const wall=(Date.now()-watchLastWall)/1000;const played=current-watchLastTime;if(!watchSeeking&&played>0&&played<=wall*1.6+0.6)watchSegments.push([watchLastTime,current]);watchLastTime=current;watchLastWall=Date.now();const point=watchCheckpoints[watchCheckpointIndex];if(point&&current>=point){watchVideo.pause();$('#checkin-overlay').style.display='block';$('#checkin-continue').style.display='inline-block';watchCheckpoints[watchCheckpointIndex]=Infinity;watchCheckpointIndex++;}updateWatchProgressUI();}
async function pushWatchProgress(){if(!watchVideo||!watchVideo.duration||watchSegments.length===0||watchComplete)return;try{const result=await api(`/api/sessions/${selectedSessionId}/progress`,{method:'POST',body:JSON.stringify({segments:watchSegments,position:watchVideo.currentTime,duration_seconds:watchVideo.duration})});const pct=result.percent;$('#watch-percent').textContent=`Watched ${pct}%`;$('#watch-needed').textContent=result.completed?'Complete · no quiz required':pct>=70?'Quiz unlocked':`${Math.max(0,70-pct).toFixed(0)}% more needed`;$('#watch-progress-bar').style.width=`${Math.min(100,pct)}%`;if(result.completed){watchComplete=true;$('#quiz-wrap').innerHTML='<div class="notice">Session complete. Your attendance has been recorded; no quiz was required.</div>';clearInterval(watchProgressTimer);await hydrate();}else if(result.quiz_unlocked)loadQuiz();}catch(error){if(error.message.includes('Skipping'))watchVideo.pause();toast(error.message);}}
function continueWatch(){$('#checkin-overlay').style.display='none';$('#checkin-continue').style.display='none';watchLastTime=watchVideo.currentTime;watchLastWall=Date.now();watchVideo.play().catch(()=>{});}
function pauseBackground(){if(document.visibilityState!=='visible'&&watchVideo&&!watchVideo.paused){watchVideo.pause();toast('Recording paused while Voxera was in the background.');}}
let quizLoaded=false;
async function loadQuiz(){if(quizLoaded)return;quizLoaded=true;try{const questions=await api(`/api/sessions/${selectedSessionId}/quiz`);$('#quiz-wrap').innerHTML=`<div class="card" style="padding:14px"><div class="card-title">Session quiz</div>${questions.map((q,i)=>`<div class="quiz-question"><h4>${i+1}. ${esc(q.question)}</h4>${q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="quiz-${i}" value="${j}"> ${esc(o)}</label>`).join('')}</div>`).join('')}<button class="btn btn-primary btn-small" onclick="submitQuiz(${questions.length})">Submit answers</button></div>`;}catch(error){quizLoaded=false;if(!error.message.includes('70%'))toast(error.message);}}
async function submitQuiz(count){const answers=[];for(let i=0;i<count;i++){const selected=$(`input[name="quiz-${i}"]:checked`);if(!selected){toast('Answer each question to continue.');return;}answers.push(Number(selected.value));}try{const result=await api(`/api/sessions/${selectedSessionId}/quiz`,{method:'POST',body:JSON.stringify({answers})});toast(result.passed?'Passed — recorded attendance saved.':'Not quite. Review the session and try the quiz again.');if(result.passed)await hydrate();}catch(error){toast(error.message);}}
function closeWatch(){clearInterval(watchProgressTimer);document.removeEventListener('visibilitychange',pauseBackground);if(watchVideo){watchVideo.pause();watchVideo.removeAttribute('src');watchVideo.load();}watchVideo=null;quizLoaded=false;$('.modal-back')?.remove();}
const watchRecordingWithoutResume=watchRecording;
watchRecording=async function(sessionId){
  const id=Number(sessionId||selectedSessionId);if(!id)return toast('Recording session not found.');
  try{
    const progress=await api(`/api/sessions/${id}/progress`);watchResumePosition=Math.max(0,Number(progress.position)||0);
    watchRecordingWithoutResume(id);
    videoComments=[];videoCommentSessionId=id;const modal=$('.modal-back .modal');if(modal)modal.insertAdjacentHTML('beforeend',videoCommentsMarkup());
    loadVideoComments(id).catch(error=>toast(`Comments could not be loaded: ${error.message}`));
    watchSegments=(progress.segments||[]).map(segment=>[Number(segment[0]),Number(segment[1])]);
    watchVideo.parentElement.classList.add('watch-media-stage');
    const progressBar=$('#watch-progress-bar')?.parentElement;progressBar?.setAttribute('role','progressbar');progressBar?.setAttribute('aria-label','Recording progress');progressBar?.setAttribute('aria-valuemin','0');progressBar?.setAttribute('aria-valuemax','100');
    const resumeNote=document.createElement('div');resumeNote.id='watch-resume-note';resumeNote.className='row-meta';resumeNote.setAttribute('aria-live','polite');watchVideo.parentElement.insertAdjacentElement('afterend',resumeNote);
    const session=Object.values(state.sessionsByProgramme||{}).flat().find(item=>Number(item.id)===id);
    if(session){const title=$('.modal-top h2');if(title)title.textContent=session.title;const detail=$('.modal-top p');if(detail)detail.textContent='Resume where you left off. Your progress is saved automatically.';}
    if(session?.captions_file){const track=document.createElement('track');track.kind='captions';track.label='English';track.srclang='en';track.default=true;track.src=`/api/sessions/${id}/captions?token=${encodeURIComponent(authToken)}`;watchVideo.append(track);}
    watchVideo.addEventListener('loadedmetadata',()=>{
      const duration=watchVideo.duration;
      if(watchResumePosition>0&&watchResumePosition<duration-2){watchVideo.currentTime=watchResumePosition;const resume=$('#watch-resume-note');if(resume)resume.textContent=`Resuming at ${Math.floor(watchResumePosition/60)}:${String(Math.floor(watchResumePosition%60)).padStart(2,'0')}`;}
      watchCheckpoints=watchCheckpoints.filter(point=>point>watchVideo.currentTime+15);
      const pct=Math.min(100,Number(progress.percent)||0);$('#watch-percent').textContent=`Watched ${pct}%`;$('#watch-needed').textContent=pct>=70?'Quiz unlocked':`${Math.max(0,70-pct).toFixed(0)}% more needed`;$('#watch-progress-bar').style.width=`${pct}%`;
      $('#watch-progress-bar')?.setAttribute('aria-valuenow',String(Math.round(pct)));
    },{once:true});
  }catch(error){toast(`Could not load saved playback progress: ${error.message}`);}
};
const closeWatchWithoutProgress=closeWatch;
closeWatch=async function(){if(watchVideo){watchVideo.pause();await pushWatchProgress();}closeWatchWithoutProgress();};

function voicePage(){const localReady=state.aiStatus?.voice?.available===true;const browserAvailable=!!(window.SpeechRecognition||window.webkitSpeechRecognition);const button=localReady?`<button class="btn btn-primary" onclick="recordVoice('speak')">${state.recording?'Stop recording':'Record a voice question'}</button>`:browserAvailable?`<button class="btn btn-primary" onclick="recordVoice('speak')">${state.recording?'Stop listening':'Use browser speech recognition'}</button>`:'';const disclosure=!localReady&&browserAvailable?'<div class="notice voice-disclosure"><b>Optional browser transcription</b><br>Your browser handles speech recognition and may send audio to its own provider. Voxera does not receive or store that audio; only the transcript is sent after you review and confirm it. You can type instead.</div>':!localReady?`<div class="notice">Local voice models are not installed for ${esc(currentUser?.language||'your language')}, and this browser does not support speech recognition. Type your question below or install the optional local voice models.</div>`:'<div class="notice">Local voice transcription is ready. Audio is sent to this Voxera server and stored only if voice-storage consent is enabled in Profile.</div>';return `<div class="voice-panel"><div class="eyebrow">VOICE & TEXT SUPPORT</div><h2>What can we help with?</h2><p>Speak in ${esc(currentUser?.language||'English')}. Review the transcript before Voxera answers or sends it to your programme team.</p><div class="voice-orb">${state.recording?lucideIcon('mic',32):lucideIcon('sparkles',32)}</div>${button}<button class="btn btn-outline" style="margin-left:7px" onclick="openModal('type-message')">Type instead</button>${disclosure}<div class="voice-status">${state.voiceText?'Transcript ready to review':localReady?'Ready for local transcription.':browserAvailable?'Browser speech recognition is optional.':'Type your message to continue.'}</div>${state.voiceText?`<div class="phone-card" style="text-align:left"><div class="eyebrow">WHAT I HEARD · ${esc(currentUser?.language||'English')}</div><textarea id="voice-edit" style="width:100%;margin:10px 0;border:1px solid var(--line);border-radius:9px;padding:10px;min-height:55px">${esc(state.voiceText)}</textarea>${state.voiceTranslation?`<div class="notice"><b>English meaning · local translation</b><br>${esc(state.voiceTranslation)}</div>`:`<div class="notice"><b>Translation unavailable</b><br>Review the transcript carefully. Type an English translation in the text box above if you want Voxera to use it.</div>`}<div style="display:flex;gap:7px;flex-wrap:wrap"><button class="btn btn-primary btn-small" onclick="confirmVoice()">Confirm and continue</button><button class="btn btn-outline btn-small" onclick="editVoice()">Edit text</button><button class="btn btn-soft btn-small" onclick="recordAgain()">Record again</button></div></div>`:''}</div>`;}
function voicePage(){const localReady=state.aiStatus?.voice?.available===true;const browserAvailable=!!(window.SpeechRecognition||window.webkitSpeechRecognition);const button=localReady?`<button class="btn btn-primary" onclick="recordVoice('speak')">${state.recording?'Stop recording':'Record a voice question'}</button>`:browserAvailable?`<button class="btn btn-primary" onclick="recordVoice('speak')">${state.recording?'Stop listening':'Use browser speech recognition'}</button>`:'';const working=state.assistantWorking===true;const status=state.voiceError|| (working?'Voxera is preparing an answer…':state.recording?'Listening. Speak clearly, then tap Stop.':state.voiceText?'Transcript ready to review':localReady?'Ready for local transcription.':browserAvailable?'Browser speech recognition is optional.':'Type your message to continue.');const disclosure=!localReady&&browserAvailable?'<div class="notice voice-disclosure"><b>Optional browser transcription</b><br>Your browser handles speech recognition and may send audio to its own provider. Voxera does not receive or store that audio; only the transcript is sent after you review and confirm it. You can type instead.</div>':!localReady?`<div class="notice">Local voice models are not installed for ${esc(currentUser?.language||'your language')}, and this browser does not support speech recognition. Type your question below.</div>`:'<div class="notice">Local voice transcription is ready. Audio is sent to this Voxera server and stored only if voice-storage consent is enabled in Profile.</div>';return `<div class="voice-panel ${state.recording?'is-listening':''} ${working?'is-working':''}"><div class="eyebrow">VOICE & TEXT SUPPORT</div><h2>What can we help with?</h2><p>Speak in ${esc(currentUser?.language||'English')}. Review the transcript before Voxera answers or sends it to your programme team.</p><div class="voice-orb ${state.recording?'is-listening':''} ${working?'is-working':''}" aria-hidden="true">${lucideIcon('audioLines',32)}</div>${button}<button class="btn btn-outline" style="margin-left:7px" onclick="openModal('type-message')">Type instead</button>${disclosure}<div class="voice-status" role="status" aria-live="polite">${esc(status)}</div>${state.voiceText?`<div class="phone-card" style="text-align:left"><div class="eyebrow">WHAT I HEARD · ${esc(currentUser?.language||'English')}</div><textarea id="voice-edit" style="width:100%;margin:10px 0;border:1px solid var(--line);border-radius:9px;padding:10px;min-height:55px">${esc(state.voiceText)}</textarea>${state.voiceTranslation?`<div class="notice"><b>English meaning · local translation</b><br>${esc(state.voiceTranslation)}</div>`:`<div class="notice"><b>Translation unavailable</b><br>Review the transcript carefully. Type an English translation in the text box above if you want Voxera to use it.</div>`}<div style="display:flex;gap:7px;flex-wrap:wrap"><button class="btn btn-primary btn-small" onclick="confirmVoice()">Confirm and continue</button><button class="btn btn-outline btn-small" onclick="editVoice()">Edit text</button><button class="btn btn-soft btn-small" onclick="recordAgain()">Record again</button></div></div>`:''}</div>`;}
function startBrowserVoiceRecognition(purpose='speak'){
  const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SpeechRecognition)return toast('Browser speech recognition is unavailable. Type your message instead.');
  voicePurpose=purpose;state.voiceText='';state.voiceTranslation='';state.voiceError='';state.voiceSource='browser';state.recording=true;
  const recognition=new SpeechRecognition();voiceRecognition=recognition;recognition.lang=({'English':'en-NG','Pidgin':'en-NG','Yoruba':'yo-NG','Hausa':'ha-NG','Igbo':'ig-NG'})[currentUser?.language||'English'];recognition.interimResults=false;recognition.maxAlternatives=1;recognition.continuous=false;
  recognition.onresult=event=>{const transcript=event.results?.[0]?.[0]?.transcript?.trim();if(transcript){state.voiceText=transcript;if(['English','Pidgin'].includes(currentUser?.language||'English'))state.voiceTranslation=transcript;state.voiceResult={source:'browser',translation_available:['English','Pidgin'].includes(currentUser?.language||'English')};}};
  recognition.onerror=event=>{const error=event.error==='not-allowed'?'Allow microphone access in your browser and try again.':event.error==='language-not-supported'?'Your browser does not support speech recognition for this language. Type instead.':event.error==='network'?'The browser speech service is unavailable. Try again or type your message.':'Browser speech recognition stopped. Type your message if the transcript was not captured.';state.voiceError=error;toast(error);};
  recognition.onend=()=>{if(voiceRecognition!==recognition)return;voiceRecognition=null;state.recording=false;if(state.voiceText&&voicePurpose==='reply')page='Speak';render();};
  try{recognition.start();render();}catch(error){voiceRecognition=null;state.recording=false;render();toast(`Browser speech recognition could not start: ${error.message}`);}
}
function stopBrowserVoiceRecognition(){if(voiceRecognition)voiceRecognition.stop();}
async function recordVoice(purpose='speak'){
  voicePurpose=purpose;
  state.voiceError='';
  if(voiceRecognition){stopBrowserVoiceRecognition();return;}
  if(voiceRecorder?.state==='recording'){voiceRecorder.stop();return;}
  if(state.aiStatus?.voice?.available!==true){startBrowserVoiceRecognition(purpose);return;}
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Voice capture needs HTTPS. Type your message instead.');return;}
  try{voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});voiceChunks=[];voiceRecorder=new MediaRecorder(voiceStream);voiceRecorder.ondataavailable=e=>{if(e.data.size)voiceChunks.push(e.data);};voiceRecorder.onstop=async()=>{voiceStream.getTracks().forEach(t=>t.stop());state.recording=false;render();const blob=new Blob(voiceChunks,{type:voiceRecorder.mimeType||'audio/webm'});const form=new FormData();form.append('file',blob,'voice-note.webm');form.append('language',currentUser?.language||'English');toast('Transcribing on this Voxera server…');try{const response=await fetch('/api/voice/transcribe',{method:'POST',headers:{Authorization:`Bearer ${authToken}`},body:form});const result=await response.json();if(!response.ok)throw new Error(result.detail||'Voice transcription failed. You can type instead.');state.voiceText=result.transcript;state.voiceTranslation=result.translation_en;state.voiceResult=result;state.recordedAudio=result.audio_stored?result.audio_path:null;if(voicePurpose==='reply')page='Speak';render();}catch(error){toast(error.message);} };voiceRecorder.start();state.recording=true;render();toast('Listening… Speak clearly, then tap Stop.');}catch(error){toast('Microphone permission was not granted. Type your message instead.');}}
async function confirmVoice(){const edit=$('#voice-edit');if(edit)state.voiceText=edit.value;try{state.voiceResult=await api('/api/voice/confirm',{method:'POST',body:JSON.stringify({text:state.voiceText,language:currentUser?.language||'English',confirmed:true})});if(voicePurpose==='reply'){const result=await api('/api/cases/from-reply',{method:'POST',body:JSON.stringify({text:state.voiceText,language:currentUser?.language||'English',confirmed:true})});toast(result.status==='escalated'?'A member of staff will follow up.':'Voxera has sent a reply.');state.voiceText='';await hydrate();render();go('Messages');return;}toast('Thanks — we checked what you said.');}catch(error){toast(error.message);}openModal('voice-confirmed');}
function messages(){const base=window.__baseMessages?.()||'';return base;}
function participantMessages(){const convs=(state.conversations||[]).filter(item=>item.kind==='programme');const active=convs.find(item=>item.id===selectedConversationId)||convs.find(item=>item.id===conversationId)||convs[0];const thread=active?(state.messages||[]):[];return `<div class="hello">YOUR CONVERSATIONS</div><h1 class="phone-title">Messages</h1><p class="page-subtitle">Private conversations with your programme teams.</p><div class="participant-message-workspace"><aside class="conversation-list participant-conversation-list"><div class="conversation-list-heading"><div><b>Chats</b><small>${convs.length} programme conversation${convs.length===1?'':'s'}</small></div><span class="message-secure-mark" aria-label="Private">●</span></div><label class="conversation-search"><span aria-hidden="true">⌕</span><input placeholder="Search conversations" oninput="filterMessageConversations(this.value)"></label><div id="participant-conversation-items">${convs.length?convs.map(item=>`<button class="conversation-button ${item.id===active?.id?'active':''}" onclick="selectConversation(${item.id})"><span class="chat-avatar">${esc(initials(item.organisation_name||'Programme'))}</span><span class="conversation-copy"><b>${esc(item.organisation_name||'Programme team')}</b><small>${esc(item.programme_title||'Programme conversation')}</small><small class="conversation-preview">${esc(item.last_message||'Start a conversation')}</small></span>${Number(item.unread_count)>0?`<span class="unread-count">${Number(item.unread_count)>99?'99+':Number(item.unread_count)}</span>`:''}</button>`).join(''):'<div class="empty">After you apply to a programme, you can message its team here.</div>'}</div></aside><section class="conversation-thread participant-chat-panel">${active?`<header class="chat-header"><span class="chat-avatar">${esc(initials(active.organisation_name||'Programme'))}</span><div class="chat-title"><b>${esc(active.organisation_name||'Programme team')}</b><small>${esc(active.programme_title||'Programme conversation')}</small></div><button class="notification-toggle" onclick="enableMessageNotifications()" aria-label="Enable message notifications" title="Enable message notifications">${window.messageNotificationsEnabled?.()?'Notifications on':'Enable alerts'}</button></header><div class="chat-notice"><span class="message-secure-mark">✓</span>Private Voxera conversation · AI responses are clearly labelled</div><div class="messages" id="participant-message-list">${thread.length?thread.map(m=>`<div class="msg ${m.ai?'ai':''} ${m.mine?'mine':''}">${esc(m.text)}<span class="msg-time">${esc(m.time||'Just now')}${m.pending?' · Waiting to send':''}</span></div>`).join(''):'<div class="chat-empty"><span class="chat-empty-icon">✦</span><b>Start the conversation</b><small>Send a message to your programme team.</small></div>'}</div><div class="chat-compose"><button class="chat-voice" aria-label="Record voice reply" title="Record voice reply" onclick="recordVoice('reply')">♬</button><input id="message-input" placeholder="Write a message" onkeydown="if(event.key==='Enter')sendMessage()"><button class="chat-send" aria-label="Send message" onclick="sendMessage()"><span>➤</span></button></div><button class="talk-to-person" onclick="escalateHuman()">Need urgent support? <b>Talk to a person</b></button>`:`<div class="chat-placeholder"><span class="chat-empty-icon">✦</span><b>Your programme conversations</b><small>Select a chat to view messages and reply to the team.</small></div>`}</section></div>`;}
const featureMessageStore='voxera-message-queue';
async function queueMessage(conversation,body){return new Promise((resolve,reject)=>{const request=indexedDB.open('voxera-offline',1);request.onupgradeneeded=()=>request.result.createObjectStore('messages',{keyPath:'id',autoIncrement:true});request.onsuccess=()=>{const tx=request.result.transaction('messages','readwrite');tx.objectStore('messages').add({conversation,body,language:currentUser?.language||'English',created:Date.now()});tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);};request.onerror=()=>reject(request.error);});}
async function sendMessage(){const input=$('#message-input');if(!input||!input.value.trim())return;const body=input.value.trim();if(!navigator.onLine){try{await queueMessage(conversationId,body);state.messages.push({text:body,mine:true,pending:true,time:'Waiting to send'});render();toast('Message queued. It will send when you reconnect.');}catch{toast('This message could not be queued on this device.');}return;}try{if(!conversationId)await hydrate();if(!conversationId)throw new Error('No conversation is available yet.');await api(`/api/conversations/${conversationId}/messages`,{method:'POST',body:JSON.stringify({body,language:currentUser?.language||'English'})});await hydrate();render();}catch(error){toast(error.message);}}
async function flushQueuedMessages(){if(!authToken||!navigator.onLine)return;try{const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('voxera-offline',1);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});const entries=await new Promise((resolve,reject)=>{const req=db.transaction('messages').objectStore('messages').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});for(const entry of entries){let conversation=entry.conversation;if(!conversation){const created=await api('/api/conversations',{method:'POST'});conversation=created.id;}await api(`/api/conversations/${conversation}/messages`,{method:'POST',body:JSON.stringify({body:entry.body,language:entry.language})});await new Promise(resolve=>{const tx=db.transaction('messages','readwrite');tx.objectStore('messages').delete(entry.id);tx.oncomplete=resolve;});}if(entries.length){await hydrate();if(page==='Messages')render();toast(`${entries.length} queued message${entries.length===1?'':'s'} sent.`);}}catch(error){console.warn('Queued messages remain stored until reconnect:',error.message);}}
window.addEventListener('online',flushQueuedMessages);
function connectMessages(){if(!authToken||messageSocket?.readyState===WebSocket.OPEN)return;const socket=new WebSocket(wsUrl());messageSocket=socket;socket.onmessage=async event=>{try{const data=JSON.parse(event.data);if(data.type==='message'||data.type==='followup'){if(window.handleIncomingMessage)await window.handleIncomingMessage(data);else{await hydrate();if(page==='Messages')render();toast('You have a new Voxera message.');}}}catch(error){console.warn('Voxera message notification failed:',error.message);}};socket.onopen=()=>{socketRetry=1000;socket.send(JSON.stringify({type:'heartbeat'}));setInterval(()=>{if(socket.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'heartbeat'}));},25000);};socket.onclose=()=>{if(messageSocket===socket)messageSocket=null;if(authToken)setTimeout(connectMessages,socketRetry);socketRetry=Math.min(30000,socketRetry*2);};socket.onerror=()=>socket.close();}

function openModal(type){if(type!=='register'&&type!=='quiz')return featureOriginalModal(type);let inner='';if(type==='register')inner=`<h2>Create your participant account</h2><p>Choose a language and review consent before registering. You can type your details or use Speak after you sign in.</p><div class="field"><label>Your name</label><input id="register-name" required placeholder="Full name"></div><div class="field"><label>Email or phone</label><input id="register-user" required placeholder="name@example.com"></div><div class="field"><label>Password</label><input id="register-password" type="password" minlength="8" placeholder="At least 8 characters"></div><div class="field"><label>Preferred language</label><select id="register-language"><option>English</option><option>Pidgin</option><option>Yoruba</option><option>Hausa</option><option>Igbo</option></select></div><div class="field"><label>Community or area (optional)</label><input id="register-area" placeholder="Area or town"></div><label class="toggle"><input type="checkbox" id="register-data" checked> I agree Voxera can use my details to provide programme services.</label><label class="toggle"><input type="checkbox" id="register-voice"> I consent to storing my voice notes after transcription.</label><label class="toggle"><input type="checkbox" id="register-remote-ai"> I agree to send confirmed text questions and my enrolments, session times, attendance summaries, recording progress, and certificates to the configured external AI provider for answers. Passwords and voice audio are not sent.</label><label class="toggle"><input type="checkbox" id="register-followup" checked> I agree to receive programme follow-up messages.</label><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="registerAccount()">Create account</button></div>`;else inner=`<h2>Session quiz</h2><div id="quiz-wrap"></div>`;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-top"><div>${inner}</div><button class="close" onclick="closeModal()">×</button></div></div></div>`);}
async function registerAccount(){const consent=$('#register-data')?.checked;if(!consent){toast('Data-use consent is required to create a Voxera account.');return;}const body={name:$('#register-name').value.trim(),username:$('#register-user').value.trim(),password:$('#register-password').value,language:$('#register-language').value,area:$('#register-area').value.trim(),consent_data:consent,consent_voice:$('#register-voice').checked,consent_remote_ai:$('#register-remote-ai').checked,consent_followup:$('#register-followup').checked};try{const result=await fetch('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.detail);return d;});authToken=result.token;currentUser=result.user;role='participant';localStorage.setItem('voxera-token',authToken);localStorage.setItem('voxera-role',role);page='Home';closeModal();await hydrate();render();toast('Welcome to Voxera. Your account is ready.');}catch(error){toast(error.message);}}

function settings(){return `${head('YOUR WORKSPACE','Settings','Set up Voxera around your organisation and demo environment.')}<section class="grid split"><article class="card"><div class="card-head"><div class="card-title">Organisation</div><button class="text-link" onclick="toast('Organisation settings saved locally')">Save changes</button></div><div class="field"><label>Organisation name</label><input value="Bright Futures Initiative"></div><div class="field"><label>Organisation type</label><select><option>NGO</option><option>LGA</option><option>Company</option></select></div><div class="field"><label>Primary language</label><select><option>English</option><option>Nigerian Pidgin</option></select></div></article><article class="card"><div class="card-head"><div class="card-title">Demo controls</div><span class="badge">Presenter tools</span></div><div class="notice">These controls change the local demo clock and generate rehearsal messages.</div><div class="record-controls"><button class="btn btn-outline btn-small" onclick="advanceDemo(1)">+1 day</button><button class="btn btn-outline btn-small" onclick="advanceDemo(7)">+1 week</button><button class="btn btn-outline btn-small" onclick="advanceDemo(30)">+1 month</button></div><div class="record-controls" style="margin-top:12px"><button class="btn btn-primary btn-small" onclick="runFollowup()">✧ Run follow-up now</button><button class="btn btn-soft btn-small" onclick="markParticipantAbsent()">Mark Amara absent</button></div><div class="profile-option"><span>Simulated days elapsed</span><b>${state.days||0}</b></div><div class="profile-option"><span>Participant message preferences</span><span class="badge">Honoured per account</span></div><div style="margin-top:16px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-outline" onclick="completeProgramme()">Complete demo Programme</button><button class="btn btn-outline" onclick="switchAdminReset()">Admin: reset data</button></div></article></section>`;}
async function advanceDemo(days){try{const result=await api('/api/demo/advance',{method:'POST',body:JSON.stringify({days})});state.days=result.offset_days;toast(`Demo clock advanced ${days} day${days===1?'':'s'}.`);}catch(error){toast(error.message);}}
async function markParticipantAbsent(){try{await api('/api/demo/absent?participant_id=2',{method:'POST'});toast('Amara marked absent for the next session.');}catch(error){toast(error.message);}}
async function completeProgramme(){try{const result=await api('/api/programmes/1/complete',{method:'POST'});await hydrate();toast(`Programme completed · ${result.certificates_issued} certificate(s) issued.`);}catch(error){toast(error.message);}}
async function switchAdminReset(){await loginDemo('admin');setTimeout(()=>openModal('reset'),150);}
async function editProgramme(id){try{const p=(await api('/api/programmes')).find(x=>x.id===id);const rows=await api(`/api/programmes/${id}/sessions`);document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-top"><div><h2>${esc(p.title)}</h2><p>Edit Programme details, session dates, attendance threshold, recording deadline, and quiz.</p></div><button class="close" onclick="closeModal()">×</button></div><label class="toggle">Certificate threshold <input type="number" id="programme-threshold" min="1" max="100" value="${p.certificate_threshold}"></label><div class="card" style="margin-top:14px;padding:13px"><b>Sessions</b>${rows.map(s=>`<div class="applicant"><span>${esc(s.title)} · ${new Date(s.scheduled_start).toLocaleDateString()}</span><span class="badge">${s.kind}</span></div>`).join('')}</div><div class="field"><label>New session title</label><input id="new-session-title" placeholder="Session title"></div><div class="field"><label>Session date and time</label><input id="new-session-date" type="datetime-local"></div><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Done</button><button class="btn btn-primary" onclick="addSession(${id})">Add session</button></div></div></div>`);}catch(error){toast(error.message);}}
async function addSession(programmeId){const title=$('#new-session-title').value.trim();const start=$('#new-session-date').value;if(!title||!start){toast('Add a session title and date.');return;}const end=new Date(new Date(start).getTime()+60*60*1000).toISOString();try{await api(`/api/programmes/${programmeId}/sessions`,{method:'POST',body:JSON.stringify({title,kind:'live_online',scheduled_start:new Date(start).toISOString(),scheduled_end:end,deadline_days:7,quiz:[]})});toast('Session added.');await hydrate();editProgramme(programmeId);closeAllButNewest();}catch(error){toast(error.message);}}
function closeAllButNewest(){const modals=document.querySelectorAll('.modal-back');modals.forEach((m,i)=>{if(i<modals.length-1)m.remove();});}

function reports(){return `${head('SEE THE DIFFERENCE','Reports','Enrolment, attendance modes, completion, follow-up and outcomes.','<button class="btn btn-outline" onclick="downloadCsv()">↓&nbsp; Export CSV</button>')}<div class="toolbar"><select class="select" id="report-programme"><option>All Programmes</option>${state.programmes.map(p=>`<option>${esc(p.title)}</option>`).join('')}</select><select class="select"><option>All time</option><option>Last 30 days</option><option>This quarter</option></select></div><section class="grid stats">${stat('Participants reached',String(state.people.length+2),'Across demo Programmes','♙')}${stat('Completion rate','72%','Certificate threshold applied','✧')}${stat('Follow-up response','64%','Responses from local messages','↩')}${stat('Certificates issued',String(state.certificates?.length||0),'Verified locally','▧')}</section><section class="grid split"><article class="card"><div class="card-head"><div class="card-title">Attendance by session</div><span class="badge">Live · recorded · physical</span></div><div class="chart">${[63,72,59,84,68,77,92].map((v,i)=>`<div class="bar-wrap"><div class="bar ${i===6?'current':''}" style="height:${v}%"></div></div>`).join('')}</div><div class="chart-labels"><span>1</span><span>2</span><span>3</span><span>4</span><span>5</span><span>6</span><span>7</span></div></article><article class="card"><div class="card-head"><div class="card-title">Absence reasons</div><span class="badge">From triage</span></div>${[['Transport','38%'],['Work schedule','29%'],['Family commitments','18%'],['Health','15%']].map(x=>`<div class="progress-row"><span>${x[0]}</span><b>${x[1]}</b></div><div class="progress" style="margin-bottom:13px"><i style="width:${x[1]};background:#e29a7e"></i></div>`).join('')}</article></section><article class="card" style="margin-top:16px"><div class="card-head"><div class="card-title">Outcome check-ins</div><span class="badge">Participant responses</span></div><div class="row-meta">Simulate one month after Programme completion to create a check-in. Replies are stored locally and appear in this report.</div><div id="outcome-list" class="programme-list" style="margin-top:12px"><div class="empty">No outcome responses yet.</div></div></article>`;}

function profile(){const certificates=state.certificates||[];return `<div class="hello">YOUR SPACE</div><h1 class="phone-title">Profile</h1><div class="phone-card"><div class="profile-head"><div class="profile-big">${currentUser?.name?.split(' ').map(x=>x[0]).join('').slice(0,2)||'AO'}</div><div><div class="row-title" style="font-size:14px">${esc(currentUser?.name||'Participant')}</div><div class="row-meta">${esc(currentUser?.area||'Lagos')} · Participant</div></div></div></div><div class="phone-section-title">Preferences & consent</div><div class="phone-card"><div class="profile-option"><span>Preferred language</span><select class="select" id="language-select" onchange="savePreferences()">${['English','Pidgin','Yoruba','Hausa','Igbo'].map(x=>`<option ${currentUser?.language===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="profile-option"><span>Store voice notes after transcription</span><input id="consent-voice" class="switch" type="checkbox" ${state.profile?.consent_voice?'checked':''} onchange="saveConsent()"></div><div class="profile-option"><span>Receive Programme follow-up</span><input id="consent-followup" class="switch" type="checkbox" ${state.profile?.consent_followup?'checked':''} onchange="saveConsent()"></div><div class="row-meta" style="padding:9px 0">When voice storage is off, audio is deleted after transcription. You can change these choices anytime.</div></div><div class="phone-section-title">My certificates</div>${certificates.length?certificates.map(c=>`<div class="cert"><div class="cert-mark">✧</div><h3>${esc(c.programme_title)}</h3><p>Issued ${new Date(c.issued_at).toLocaleDateString()} · Verify code ${esc(c.code)}</p><a class="text-link" href="/verify/${encodeURIComponent(c.code)}">Verify certificate →</a></div>`).join(''):'<div class="cert"><div class="cert-mark">✧</div><h3>Your certificates will appear here</h3><p>Complete a Programme and meet its attendance threshold to earn a certificate.</p></div>'}<div class="phone-section-title">Your participant code</div><div class="phone-card" style="text-align:center"><img id="participant-qr" alt="Participant check-in QR code" style="width:132px;height:132px;margin:10px auto;display:block"><div class="row-meta">Show this code to your facilitator at an in-person session</div></div>`;}

function verifyPage(code){return `<div class="shell">${topbar()}<main class="content" style="max-width:680px"><div class="card" style="text-align:center;padding:42px"><div class="brandmark" style="margin:auto">v</div><h1 class="page-title">Certificate verification</h1><div id="verification-result" class="notice">Checking this certificate…</div><button class="btn btn-outline" onclick="history.back()">Back</button></div></main></div>`;}
function verifyOnLoad(){const match=location.pathname.match(/^\/verify\/([^/]+)/);if(!match)return false;authToken=localStorage.getItem('voxera-token')||'';document.getElementById('app').innerHTML=verifyPage(decodeURIComponent(match[1]));fetch(`/verify/${encodeURIComponent(decodeURIComponent(match[1]))}`).then(r=>r.json()).then(result=>{$('#verification-result').className=result.valid?'notice':'notice pill-red';$('#verification-result').innerHTML=result.valid?`Valid certificate<br><b>${esc(result.certificate.participant_name)}</b><br>${esc(result.certificate.programme_title)}<br>Issued ${new Date(result.certificate.issued_at).toLocaleDateString()}`:'This certificate code could not be verified.';}).catch(()=>{$('#verification-result').textContent='Could not verify this certificate right now.';});return true;}

function participantPhysicalSessions(){return (state.enrolments||[]).filter(e=>['enrolled','completed'].includes(e.status)).flatMap(e=>(state.sessionsByProgramme?.[e.programme_id]||[]).filter(s=>s.kind==='physical'));}
function openParticipantQrScanner(){const sessions=participantPhysicalSessions();if(!sessions.length)return toast('There are no in-person sessions available for your enrolled programmes.');selectedSessionId=sessions[0].id;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" onclick="if(event.target===this){stopQrScanner();closeModal()}"><div class="modal"><div class="modal-top"><div><h2>Check in to an in-person session</h2><p>Choose the session, then scan the QR code displayed by your facilitator.</p></div><button class="close" onclick="stopQrScanner();closeModal()">×</button></div><div class="field"><label>Session</label><select class="select" onchange="selectLiveSession(this.value)">${sessions.map(s=>`<option value="${s.id}" ${s.id===selectedSessionId?'selected':''}>${esc(s.programme_title||'Programme')} · ${esc(s.title)} · ${dateLabel(s.scheduled_start)}</option>`).join('')}</select></div><video id="scan-camera" class="scan-video" playsinline></video><div class="record-controls"><button class="btn btn-primary btn-small" onclick="installQrScanner()">Open camera scanner</button></div><div class="row-meta">If your browser cannot scan QR codes, ask the facilitator to scan your personal code from Profile.</div></div></div>`);}
function installQrScanner(){const video=$('#scan-camera');const sessionId=Number(selectedSessionId);if(!video){toast('Scanner is not open.');return;}if(!sessionId){toast('Choose the session for this check-in first.');return;}if(!('BarcodeDetector'in window)){toast('This browser cannot scan QR codes directly. Ask the facilitator to scan your personal code from Profile.');return;}if(!navigator.mediaDevices?.getUserMedia){toast('Camera scanning requires HTTPS or localhost. Ask the facilitator to scan your personal code.');return;}navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}}).then(stream=>{qrStream=stream;video.srcObject=stream;video.play();const detector=new BarcodeDetector({formats:['qr_code']});qrTimer=setInterval(async()=>{try{const codes=await detector.detect(video);if(codes.length){clearInterval(qrTimer);const token=codes[0].rawValue;const result=await api(`/api/qr/checkin?session_id=${sessionId}`,{method:'POST',body:JSON.stringify({qr_token:token})});toast(`Participant ${result.participant_id} checked in.`);stopQrScanner();await hydrate();closeModal();}}catch(error){toast(error.message);stopQrScanner();}},600);}).catch(()=>toast('Allow camera access or use manual check-in.'));}
function stopQrScanner(){clearInterval(qrTimer);qrTimer=null;qrStream?.getTracks().forEach(t=>t.stop());qrStream=null;}
function featureModal(type){if(type!=='register'&&type!=='qr'&&type!=='reset')return featureOriginalModal(type);if(type==='register'){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal"><h2>Create your participant account</h2><p>Set your language and consent choices. You can change them later in Profile.</p><div class="field"><label>Your name</label><input id="register-name" placeholder="Full name"></div><div class="field"><label>Email or phone</label><input id="register-user" placeholder="name@example.com"></div><div class="field"><label>Password</label><input id="register-password" type="password" minlength="8" placeholder="At least 8 characters"></div><div class="field"><label>Preferred language</label><select id="register-language">${['English','Pidgin','Yoruba','Hausa','Igbo'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Community or area (optional)</label><input id="register-area" placeholder="Area or town"></div><label class="toggle"><input type="checkbox" id="register-data" checked> I agree Voxera can use my details for Programme services.</label><label class="toggle"><input type="checkbox" id="register-voice"> I consent to storing my voice notes after transcription.</label><label class="toggle"><input type="checkbox" id="register-followup" checked> I agree to receive Programme follow-up messages.</label><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="registerAccount()">Create account</button></div></div></div>`);return;}if(type==='qr'){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" onclick="if(event.target===this){stopQrScanner();closeModal()}"><div class="modal"><div class="modal-top"><div><h2>Physical attendance</h2><p>Scan a participant code or show a session code for participants to scan.</p></div><button class="close" onclick="stopQrScanner();closeModal()">×</button></div><video id="scan-camera" class="scan-video" playsinline></video><div class="record-controls" style="margin-top:12px"><button class="btn btn-primary btn-small" onclick="installQrScanner()">Open camera scanner</button><button class="btn btn-outline btn-small" onclick="showSessionQr()">Show session QR</button><button class="btn btn-soft btn-small" onclick="markAttendance()">Demo: mark Amara present</button></div><div id="session-qr-holder"></div></div></div>`);return;}featureOriginalModal('reset');}
async function showSessionQr(){const sessionId=Number(selectedSessionId);if(!sessionId)return toast('Choose a session first.');try{const response=await fetch(`/api/qr/${sessionId}`,{headers:{Authorization:`Bearer ${authToken}`}});if(!response.ok)throw new Error('Could not create the session QR.');const blob=await response.blob();const url=URL.createObjectURL(blob);$('#session-qr-holder').innerHTML=`<div class="card" style="text-align:center;margin-top:15px"><img src="${url}" alt="Session check-in QR" style="width:180px;height:180px"><div class="row-meta">Participants can scan this QR in the Voxera app to check in.</div></div>`;}catch(error){toast(error.message);}}
async function updateStaticImages(){if(role!=='participant'||page!=='Profile'&&page!=='My Programmes')return;const image=$('#participant-qr');if(image)try{const response=await fetch('/api/profile/qr',{headers:{Authorization:`Bearer ${authToken}`}});if(response.ok)image.src=URL.createObjectURL(await response.blob());}catch{}const voice=$('#consent-voice');const follow=$('#consent-followup');if(voice&&state.profile)voice.checked=!!state.profile.consent_voice;if(follow&&state.profile)follow.checked=!!state.profile.consent_followup;}
async function pollOutcomes(){if(role!=='organiser'||page!=='Reports')return;try{const data=await api('/api/reports');const target=$('#outcome-list');if(!target)return;const rows=data.outcome_responses||[];target.innerHTML=rows.length?rows.map(o=>`<div class="programme-row"><span class="mini-avatar">${o.response?'✓':'◷'}</span><div class="row-main"><div class="row-title">${esc(o.participant_name)} · ${esc(o.programme_title)}</div><div class="row-meta">${esc(o.milestone)} · ${esc(o.response||'Awaiting response')}</div></div><span class="badge">${o.response?'Received':'Sent'}</span></div>`).join(''):'<div class="empty">No outcome responses yet.</div>';}catch{}}
function physicalSessionsForOrganisation(){return Object.entries(state.sessionsByProgramme||{}).flatMap(([programmeId,sessions])=>sessions.filter(session=>session.kind==='physical').map(session=>({...session,programme_id:Number(programmeId),programme_title:session.programme_title||state.programmes.find(programme=>Number(programme.id)===Number(programmeId))?.title||'Programme'})));}
function physicalSessionsForParticipant(){return (state.enrolments||[]).filter(enrolment=>['enrolled','completed'].includes(enrolment.status)).flatMap(enrolment=>(state.sessionsByProgramme?.[enrolment.programme_id]||[]).filter(session=>session.kind==='physical').map(session=>({...session,programme_id:Number(enrolment.programme_id),programme_title:session.programme_title||state.programmes.find(programme=>Number(programme.id)===Number(enrolment.programme_id))?.title||'Programme'})));}
function physicalAttendanceEnrolments(sessionId){const session=physicalSessionsForOrganisation().find(item=>Number(item.id)===Number(sessionId));return (state.enrolments||[]).filter(enrolment=>Number(enrolment.programme_id)===Number(session?.programme_id)&&['enrolled','completed'].includes(enrolment.status));}
function attendanceQrModalMarkup(participant=false){
  const sessions=participant?physicalSessionsForParticipant():physicalSessionsForOrganisation();
  const currentId=participant?participantQrSessionId:attendanceQrSessionId;
  const selected=sessions.find(session=>Number(session.id)===Number(currentId))||sessions[0];
  const programmes=[...new Map(sessions.map(session=>[Number(session.programme_id),{id:Number(session.programme_id),title:session.programme_title}])).values()];
  const programmeId=Number(selected?.programme_id)||programmes[0]?.id;
  const programmeSessions=sessions.filter(session=>Number(session.programme_id)===Number(programmeId));
  const session=programmeSessions.find(item=>Number(item.id)===Number(selected?.id))||programmeSessions[0];
  if(participant)participantQrSessionId=session?.id||null;else attendanceQrSessionId=session?.id||null;
  const enrolments=participant?[]:physicalAttendanceEnrolments(session?.id);
  const participantId=participant?'participant-qr':'attendance-qr';
  return `<div class="modal-back physical-attendance-backdrop" onclick="if(event.target===this){stopQrScanner();closeModal()}"><div class="modal"><div class="modal-top"><div><h2>${participant?'Check in to an in-person session':'Physical attendance check-in'}</h2><p>${participant?'Choose the class, then scan the session code displayed by the organiser.':'Choose the programme session first. Every scan will be recorded against this session.'}</p></div><button class="close" onclick="stopQrScanner();closeModal()" aria-label="Close attendance scanner">×</button></div><div class="field"><label for="${participantId}-programme">Programme</label><select id="${participantId}-programme" class="select" onchange="changeAttendanceQrProgramme(this.value,${participant})">${programmes.map(item=>`<option value="${item.id}" ${item.id===programmeId?'selected':''}>${esc(item.title)}</option>`).join('')}</select></div><div class="field"><label for="${participantId}-session">In-person session</label><select id="${participantId}-session" class="select" onchange="changeAttendanceQrSession(this.value,${participant})">${programmeSessions.map(item=>`<option value="${item.id}" ${Number(item.id)===Number(session?.id)?'selected':''}>${esc(item.title)} · ${dateLabel(item.scheduled_start)}</option>`).join('')}</select></div><div class="notice" id="attendance-qr-session-note">${session?`Check-in records will be saved to <b>${esc(session.programme_title)} · ${esc(session.title)} · ${dateLabel(session.scheduled_start)}</b>.`:'No in-person session is available for this programme.'}</div>${participant?`<video id="scan-camera" class="scan-video" playsinline></video><div class="record-controls"><button class="btn btn-primary btn-small" onclick="installQrScanner(true)" ${session?'':'disabled'}>Scan session QR</button></div><div class="row-meta">If you cannot scan the code, ask the organiser to scan your one personal code from Profile.</div>`:`<video id="scan-camera" class="scan-video" playsinline></video><div class="record-controls" style="margin-top:12px"><button class="btn btn-primary btn-small" onclick="installQrScanner()" ${session?'':'disabled'}>Scan participant QR</button><button class="btn btn-outline btn-small" onclick="showSessionQr()" ${session?'':'disabled'}>Show session QR</button></div><details class="physical-manual-checkin"><summary>Record attendance manually</summary><div class="field"><label for="physical-attendance-participant">Enrolled participant</label><select id="physical-attendance-participant" class="select">${enrolments.map(item=>`<option value="${item.participant_id}">${esc(item.participant_name)}</option>`).join('')||'<option value="">No enrolled participants for this session</option>'}</select></div><button class="btn btn-outline btn-small" type="button" onclick="markPhysicalAttendanceManually()" ${enrolments.length?'':'disabled'}>Mark present for this session</button></details><div id="session-qr-holder"></div>`}</div></div>`;
}
function openPhysicalAttendance(programmeId=null,sessionId=null){if(role!=='organiser'&&role!=='admin')return toast('Only organisers can mark programme attendance.');const sessions=physicalSessionsForOrganisation();if(!sessions.length)return toast('Add an in-person session to a programme before marking physical attendance.');const selected=sessions.find(session=>Number(session.id)===Number(sessionId))||sessions.find(session=>Number(session.programme_id)===Number(programmeId))||sessions[0];attendanceQrSessionId=selected.id;stopQrScanner();document.body.insertAdjacentHTML('beforeend',attendanceQrModalMarkup(false));}
function changeAttendanceQrProgramme(programmeId,participant=false){const sessions=participant?physicalSessionsForParticipant():physicalSessionsForOrganisation();const first=sessions.find(session=>Number(session.programme_id)===Number(programmeId));if(participant)participantQrSessionId=first?.id||null;else attendanceQrSessionId=first?.id||null;refreshAttendanceQrModal(participant);}
function changeAttendanceQrSession(sessionId,participant=false){if(participant)participantQrSessionId=Number(sessionId)||null;else attendanceQrSessionId=Number(sessionId)||null;stopQrScanner();refreshAttendanceQrModal(participant);}
function refreshAttendanceQrModal(participant=false){const backdrop=$('.physical-attendance-backdrop');if(!backdrop)return;stopQrScanner();const wrapper=document.createElement('div');wrapper.innerHTML=attendanceQrModalMarkup(participant);backdrop.replaceWith(wrapper.firstElementChild);}
function openParticipantQrScanner(){const sessions=physicalSessionsForParticipant();if(!sessions.length)return toast('There are no in-person sessions available for your enrolled programmes.');participantQrSessionId=sessions[0].id;document.body.insertAdjacentHTML('beforeend',attendanceQrModalMarkup(true));}
installQrScanner=function(participant=false){const video=$('#scan-camera'),sessionId=Number(participant?participantQrSessionId:attendanceQrSessionId);if(!video)return toast('Scanner is not open.');if(!sessionId)return toast('Choose the in-person session for this check-in first.');if(!('BarcodeDetector'in window))return toast(participant?'This browser cannot scan QR codes. Ask your facilitator to scan your personal code from Profile.':'This browser cannot scan QR codes. Show the session QR or use manual check-in instead.');if(!navigator.mediaDevices?.getUserMedia)return toast('Camera scanning requires HTTPS or localhost.');if(qrStream)return; navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}}).then(stream=>{qrStream=stream;video.srcObject=stream;video.play();const detector=new BarcodeDetector({formats:['qr_code']});qrTimer=setInterval(async()=>{try{const codes=await detector.detect(video);if(!codes.length)return;clearInterval(qrTimer);const result=await api(`/api/qr/checkin?session_id=${sessionId}`,{method:'POST',body:JSON.stringify({qr_token:codes[0].rawValue})});toast(`${result.participant_name||'Participant'} checked in to ${result.session_title||'the selected session'}.`);stopQrScanner();await hydrate();closeModal();}catch(error){toast(error.message);stopQrScanner();}},600);}).catch(()=>toast('Allow camera access or use the session QR or manual check-in instead.'));};
async function markPhysicalAttendanceManually(){const sessionId=Number(attendanceQrSessionId),participantId=Number($('#physical-attendance-participant')?.value);if(!sessionId||!participantId)return toast('Choose an enrolled participant and physical session.');try{const result=await api(`/api/sessions/${sessionId}/attendance?participant_id=${participantId}&mode=physical_manual`,{method:'POST'});const enrolment=physicalAttendanceEnrolments(sessionId).find(item=>Number(item.participant_id)===participantId);const session=physicalSessionsForOrganisation().find(item=>Number(item.id)===sessionId);toast(`${enrolment?.participant_name||'Participant'} marked present for ${session?.title||'this session'}.`);if(result.marked){stopQrScanner();await hydrate();closeModal();}}catch(error){toast(error.message);}}
featureModal=function(type){if(type==='qr'){openPhysicalAttendance();return;}return featureModalOriginal(type);};
const featureModalOriginal=window.openModal;
window.openModal=featureModal;
showSessionQr=async function(){const sessionId=Number(attendanceQrSessionId);if(!sessionId)return toast('Choose an in-person session first.');try{const response=await fetch(`/api/qr/${sessionId}`,{headers:{Authorization:`Bearer ${authToken}`}});if(!response.ok){let detail='Could not create the session QR.';try{detail=(await response.json()).detail||detail;}catch{}throw new Error(detail);}const blob=await response.blob(),url=URL.createObjectURL(blob),session=physicalSessionsForOrganisation().find(item=>Number(item.id)===sessionId);$('#session-qr-holder').innerHTML=`<div class="card" style="text-align:center;margin-top:15px"><img src="${url}" alt="Session check-in QR" style="width:180px;height:180px"><div class="row-meta">Participants can scan the session QR to check in to ${esc(session?.title||'this session')}.</div></div>`;}catch(error){toast(error.message);}};
const updateStaticImagesWithoutQrScanner=updateStaticImages;
updateStaticImages=async function(){const image=$('#participant-qr');if(role==='participant'&&image&&!$('#participant-qr-scan'))image.insertAdjacentHTML('afterend','<button id="participant-qr-scan" class="btn btn-outline btn-small" style="margin:8px auto" onclick="openParticipantQrScanner()">Scan an in-person session QR</button>');await updateStaticImagesWithoutQrScanner();};
function advanceOffline(){return;}

function simulatePresence(){toast('Presence simulation is unavailable. Join a real live session to record participant presence.');}
window.openModal=featureModal;window.registerAccount=registerAccount;window.joinLiveClass=joinLiveClass;window.leaveLive=leaveLive;window.toggleLive=toggleLive;window.simulatePresence=simulatePresence;window.advanceDemo=advanceDemo;window.markParticipantAbsent=markParticipantAbsent;window.completeProgramme=completeProgramme;window.approveEnrollment=approveEnrollment;window.addSession=addSession;window.watchRecording=watchRecording;window.closeWatch=closeWatch;window.continueWatch=continueWatch;window.submitQuiz=submitQuiz;window.recordVoice=recordVoice;window.confirmVoice=confirmVoice;window.programmes=programmes;window.liveClass=liveClass;window.participant=participant;window.myProgrammes=myProgrammes;window.participantMessages=participantMessages;window.messages=messages;window.settings=settings;window.reports=reports;window.profile=profile;window.editProgramme=editProgramme;window.stopQrScanner=stopQrScanner;window.showSessionQr=showSessionQr;
window.openParticipantQrScanner=openParticipantQrScanner;window.installQrScanner=installQrScanner;window.uploadClassRecording=uploadClassRecording;window.generateRecordingCaptions=generateRecordingCaptions;
window.attachParticipantLiveVideo=attachParticipantLiveVideo;
const baseRender=window.render;
const renderTimer=setInterval(()=>{if(typeof currentUser!=='undefined'&&authToken){clearInterval(renderTimer);connectMessages();window.addEventListener('online',flushQueuedMessages);setTimeout(updateStaticImages,250);setInterval(pollOutcomes,2500);}},500);
const loginObserver=new MutationObserver(()=>{const target=$('.login-card');if(target&&!$('#register-button')){const button=document.createElement('button');button.id='register-button';button.className='btn btn-outline';button.style='width:100%;margin-top:9px';button.textContent='Create a participant account';button.onclick=()=>featureModal('register');target.append(button);}});
loginObserver.observe(document.getElementById('app'),{childList:true,subtree:true});
if($('.login-card')){const register=document.createElement('button');register.id='register-button';register.className='btn btn-outline';register.style='width:100%;margin-top:9px';register.textContent='Create a participant account';register.onclick=()=>featureModal('register');$('.login-card').append(register);}
if(verifyOnLoad())loginObserver.disconnect();else if(authToken)setTimeout(()=>{if(typeof hydrate==='function')hydrate().then(()=>{if(typeof render==='function')render();connectMessages();setTimeout(updateStaticImages,200);});},300);
